nilla","size":"Vanilla","color":"Amber","sku":"EN-CRS-VAN","price":699,"compareAt":799},{"id":"the-cozy-ritual-set::lemongrass","size":"Lemongrass","color":"Amber","sku":"EN-CRS-LG","price":699,"compareAt":799},{"id":"the-cozy-ritual-set::bubblegum","size":"Bubblegum","color":"Amber","sku":"EN-CRS-BG","price":699,"compareAt":799},{"id":"the-cozy-ritual-set::mint","size":"Mint","color":"Amber","sku":"EN-CRS-MNT","price":699,"compareAt":799},{"id":"the-cozy-ritual-set::sandalwood","size":"Sandalwood","color":"Amber","sku":"EN-CRS-SW","price":699,"compareAt":799},{"id":"the-cozy-ritual-set::cinnamon-orange","size":"Cinnamon Orange","color":"Amber","sku":"EN-CRS-CO","price":699,"compareAt":799}],"category":"Custom Orders","discount":13}');
